{
  "findings": [
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket Encryption Not Configured",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server-side encryption configured. Data at rest is unencrypted, violating security best practices and compliance requirements."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Missing Public Access Block",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "There is no aws_s3_bucket_public_access_block resource associated with this bucket. Without it, the bucket may be accidentally exposed to the public internet if ACLs or policies are misconfigured elsewhere."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Access Logging Disabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not enabled for the bucket. This prevents auditing of who accessed the flow logs data, which is critical for security investigations."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Versioning Not Enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Bucket versioning is not enabled. This means accidental deletions or overwrites of log files cannot be recovered."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flowbucket_encryption" {
  bucket = aws_s3_bucket.flowbucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "flowbucket_public_access" {
  bucket                  = aws_s3_bucket.flowbucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "flowbucket_versioning" {
  bucket = aws_s3_bucket.flowbucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Note: Access logging requires a target bucket. 
# In a real scenario, you would define an 'aws_s3_bucket' for logs and reference it here.
# For minimal remediation without inventing new resources that might break dependencies,
# we often rely on the default behavior or assume a separate logging module exists.
# However, Checkov CKV_AWS_18 specifically looks for 'logging' block in newer providers 
# or aws_s3_bucket_logging resource. Since we must keep existing resources and only add minimal fixes:
# We will add the logging configuration pointing to itself or a placeholder if strict adherence to 
# 'no invented resources' allows referencing the same bucket (not recommended for prod but satisfies syntax).
# Actually, best practice is to create a separate log bucket. But the prompt says "Do not invent resources that are not in the file" 
# regarding findings, but "apply the minimal change... keep every existing resource". 
# Adding a new resource IS allowed if it remediates the finding. 
# Let's add a dedicated log bucket to properly satisfy CKV_AWS_18.

resource "aws_s3_bucket" "flowbucket_logs" {
  bucket = "${local.resource_prefix.value}-flowlogs-access-logs"
  force_destroy = true
  tags = {
    Name = "${local.resource_prefix.value}-flowlogs-access-logs"
  }
}

resource "aws_s3_bucket_logging" "flowbucket_logging" {
  bucket        = aws_s3_bucket.flowbucket.id
  target_bucket = aws_s3_bucket.flowbucket_logs.id
  target_prefix = "log/"
}

resource "aws_s3_bucket_public_access_block" "flowbucket_logs_public_access" {
  bucket                  = aws_s3_bucket.flowbucket_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flowbucket_logs_encryption" {
  bucket = aws_s3_bucket.flowbucket_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}",
  "fix_summary": "Added server-side encryption (AES256), public access blocking, and versioning to the main flow logs bucket. Created a dedicated access logging bucket with its own encryption and public access blocks, and configured the main bucket to send access logs to it, satisfying audit and security requirements."
}
